//! `aliases.rs`: org-roam's `ROAM_ALIASES` reader, checked against Emacs, and
//! the rule that says which source a node's aliases come from.

use std::collections::HashMap;

use proptest::prelude::*;

use super::aliases::*;
use super::*;

/// What Emacs 30.2 / Org 9.7 returned for each input, regenerated by
/// `data/split_string_and_unquote.el` (see its header).
const ORACLE: &str = include_str!("data/split_string_and_unquote.jsonl");

/// Inputs Emacs reads and MAE deliberately refuses (`Unsupported`): a key
/// modifier, a raw byte, a lone surrogate, a non-Unicode code point or a
/// character name. Each must still be in the oracle as an Emacs success, so the
/// register cannot outlive the divergence it records.
const DIVERGENCES: &[&str] = &[
    "\"\\C-a\"",
    "\"\\^I\"",
    "\"\\M-a\"",
    "\"\\S-a\"",
    "\"\\200\"",
    "\"\\xe9\"",
    "\"é\\xe9\"",
    "\"\\x80\"",
    "\"\\ud800\"",
    "\"\\x110000\"",
    "\"\\N{LATIN SMALL LETTER E WITH ACUTE}\"",
];

/// Every oracle case: MAE returns exactly what Emacs does, errors where Emacs
/// errors, and refuses (never approximates) each registered divergence.
#[test]
fn split_string_and_unquote_matches_emacs() {
    let mut checked = 0;
    let mut divergences_seen = Vec::new();
    for line in ORACLE.lines() {
        let v: serde_json::Value = serde_json::from_str(line).unwrap();
        let Some(input) = v["in"].as_str() else {
            assert!(v["emacs"].is_string(), "unrecognised oracle line {line}");
            continue;
        };
        let ours = split_string_and_unquote(input);
        if DIVERGENCES.contains(&input) {
            assert!(
                v["ok"].is_array(),
                "{input:?}: registered divergence, but Emacs errors"
            );
            match ours {
                Err(UnquoteError {
                    kind: UnquoteErrorKind::Unsupported(_),
                    ..
                }) => {}
                other => panic!("{input:?}: expected Unsupported, got {other:?}"),
            }
            divergences_seen.push(input.to_string());
        } else if let Some(ok) = v["ok"].as_array() {
            let want: Vec<String> = ok
                .iter()
                .map(|s| {
                    s.as_array()
                        .unwrap()
                        .iter()
                        .map(|c| char::from_u32(c.as_u64().unwrap() as u32).unwrap())
                        .collect()
                })
                .collect();
            assert_eq!(ours.as_ref(), Ok(&want), "{input:?}");
        } else {
            assert!(v["err"].is_string(), "{line}");
            assert!(
                ours.is_err(),
                "{input:?}: Emacs errors ({}), MAE read {ours:?}",
                v["err"]
            );
        }
        checked += 1;
    }
    assert_eq!(
        divergences_seen.len(),
        DIVERGENCES.len(),
        "register entries missing from the oracle"
    );
    assert!(checked >= 80, "only {checked} oracle cases ran");
}

/// The cases the format exists for, readable without the oracle file.
#[test]
fn split_string_and_unquote_reads_org_roam_values() {
    let s = |v: &[&str]| v.iter().map(|x| x.to_string()).collect::<Vec<_>>();
    assert_eq!(
        split_string_and_unquote("foo \"bar baz\""),
        Ok(s(&["foo", "bar baz"]))
    );
    assert_eq!(
        split_string_and_unquote("\"a \\\"q\\\" b\" c"),
        Ok(s(&["a \"q\" b", "c"]))
    );
    assert_eq!(split_string_and_unquote(""), Ok(vec![]));
    let e = split_string_and_unquote("ok \"never closed").unwrap_err();
    assert_eq!((e.offset, e.kind), (3, UnquoteErrorKind::Unterminated));
}

/// Quote any list of aliases the way org-roam writes them (`\` and `"` escaped
/// inside quotes); reading it back returns the list. Arbitrary text, including
/// whitespace, quotes, backslashes and non-ASCII.
fn quote(aliases: &[String]) -> String {
    aliases
        .iter()
        .map(|a| format!("\"{}\"", a.replace('\\', "\\\\").replace('"', "\\\"")))
        .collect::<Vec<_>>()
        .join(" ")
}

proptest! {
    #[test]
    fn quoted_aliases_round_trip(aliases in proptest::collection::vec(any::<String>(), 0..6)) {
        prop_assert_eq!(split_string_and_unquote(&quote(&aliases)), Ok(aliases));
    }

    /// Never panics, whatever the property holds.
    #[test]
    fn arbitrary_input_never_panics(s in any::<String>()) {
        let _ = split_string_and_unquote(&s);
    }

    /// Text with no quote is split on Emacs whitespace and nothing else.
    #[test]
    fn unquoted_text_splits_on_emacs_whitespace(s in "[^\"]{0,40}") {
        let want: Vec<String> = s
            .split(is_emacs_whitespace)
            .filter(|w| !w.is_empty())
            .map(str::to_string)
            .collect();
        prop_assert_eq!(split_string_and_unquote(&s), Ok(want));
    }
}

fn props(kv: &[(&str, &str)]) -> HashMap<String, String> {
    kv.iter()
        .map(|(k, v)| (k.to_string(), v.to_string()))
        .collect()
}

const LIT: Option<&str> = Some(BODY_FORMAT_ORG_LITERAL_V1);

/// In an org-literal KB the property is the source; the array, even when set,
/// is not, and that is reported rather than silently merged or dropped.
#[test]
fn org_literal_reads_the_property_and_ignores_the_array() {
    let p = props(&[("ID", "x"), ("ROAM_ALIASES", "foo \"bar baz\"")]);
    let got = node_aliases(LIT, &[], &p);
    assert_eq!(got.aliases, vec!["foo", "bar baz"]);
    assert!(got.problems.is_empty());

    let illegal = vec!["from-array".to_string()];
    let got = node_aliases(LIT, &illegal, &p);
    assert_eq!(got.aliases, vec!["foo", "bar baz"]);
    assert_eq!(
        got.problems,
        vec![AliasProblem::ArrayIgnored {
            values: illegal.clone()
        }]
    );
    // No property at all: still not the array.
    let got = node_aliases(LIT, &illegal, &props(&[("ID", "x")]));
    assert!(got.aliases.is_empty());
}

/// Every other KB keeps the array as the source, and a `ROAM_ALIASES` property
/// there means nothing — including a body format that only looks similar.
#[test]
fn native_kb_reads_the_array() {
    let p = props(&[("ROAM_ALIASES", "from-property")]);
    let arr = vec!["one".to_string(), "two words".to_string()];
    for fmt in [
        None,
        Some(""),
        Some("org-literal-v2"),
        Some("ORG-LITERAL-V1"),
    ] {
        let got = node_aliases(fmt, &arr, &p);
        assert_eq!(got.aliases, arr, "{fmt:?}");
        assert!(got.problems.is_empty(), "{fmt:?}");
    }
}

/// Org matches property names case-insensitively; two spellings at once pick
/// the same one on every reader and say so.
#[test]
fn property_name_is_case_insensitive_and_ambiguity_is_reported() {
    let got = node_aliases(LIT, &[], &props(&[("roam_aliases", "low")]));
    assert_eq!(got.aliases, vec!["low"]);

    let got = node_aliases(
        LIT,
        &[],
        &props(&[("roam_aliases", "low"), ("ROAM_ALIASES", "up")]),
    );
    assert_eq!(got.aliases, vec!["up"]);
    assert_eq!(
        got.problems,
        vec![AliasProblem::AmbiguousProperty {
            keys: vec!["ROAM_ALIASES".into(), "roam_aliases".into()],
            used: "ROAM_ALIASES".into(),
        }]
    );
}

/// A value Emacs cannot read gives no aliases (as org-roam gets none) and a
/// problem naming why — never a partial guess, never silence.
#[test]
fn malformed_property_gives_no_aliases_and_a_problem() {
    let got = node_aliases(LIT, &[], &props(&[("ROAM_ALIASES", "good \"bad")]));
    assert!(got.aliases.is_empty());
    match got.problems.as_slice() {
        [AliasProblem::Malformed { property, error }] => {
            assert_eq!(property, "ROAM_ALIASES");
            assert_eq!(error.kind, UnquoteErrorKind::Unterminated);
        }
        other => panic!("{other:?}"),
    }
    assert!(got.problems[0].to_string().contains("unterminated"));
}

/// Through a real node document: the derived value follows the property as it
/// is edited, and the array written beside it is never what is reported.
#[test]
fn node_doc_aliases_follow_the_property() {
    let mut doc = KbNodeDoc::new("n1", "T", "", &[]);
    let _ = doc.set_properties(&props(&[("ROAM_ALIASES", "foo \"bar baz\"")]));
    assert_eq!(doc.aliases_in(LIT).aliases, vec!["foo", "bar baz"]);
    assert!(
        doc.aliases().is_empty(),
        "nothing copies the property into the array"
    );

    let _ = doc.set_properties(&props(&[("ROAM_ALIASES", "\"only one\"")]));
    assert_eq!(doc.aliases_in(LIT).aliases, vec!["only one"]);

    let _ = doc.set_aliases(&["array-value".to_string()]);
    assert_eq!(doc.aliases_in(LIT).aliases, vec!["only one"]);
    assert_eq!(doc.aliases_in(None).aliases, vec!["array-value"]);
}
